/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  random,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type DiscordJoinAnimationProps = Record<string, any>;

const DiscordJoinAnimation: React.FC<DiscordJoinAnimationProps> = ({
  backgroundColor = "#050507",
  transparentBackground = false,
  durationInSeconds = 8,
  primaryColor = "#3b82f6",
  cardColor = "#121215",
  serverName = "Malloy Studio",
  inviterName = "Wumpus",
  memberCount = 1337,
  onlineCount = 420,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  // Background parsing
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Background Particles (Blue glow effect)
  const particles = React.useMemo(() => {
    return new Array(15).fill(0).map((_, i) => ({
      x: random(`x-${i}`),
      y: random(`y-${i}`),
      size: random(`size-${i}`) * 200 + 100,
      speed: random(`speed-${i}`) * 80 + 20,
      opacity: random(`opacity-${i}`) * 0.15 + 0.05,
    }));
  }, []);

  // Animation Springs & Interpolations
  // 1. Intro Card Animation
  const cardIntroProgress = spring({
    frame: frame - 10,
    fps,
    config: { damping: 14, stiffness: 100 },
  });

  // 2. Elements staggering
  const headerOpacity = interpolate(frame, [20, 35], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const headerY = interpolate(frame, [20, 35], [10, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.ease),
  });

  const serverIconSpring = spring({
    frame: frame - 25,
    fps,
    config: { damping: 12, stiffness: 120 },
  });

  const serverInfoOpacity = interpolate(frame, [30, 45], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const serverInfoX = interpolate(frame, [30, 45], [-15, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.ease),
  });

  const buttonSpring = spring({
    frame: frame - 40,
    fps,
    config: { damping: 14 },
  });

  // 3. Click Sequence
  const clickStartFrame = durationInFrames - 60;
  const clickReleaseFrame = durationInFrames - 50;

  const pressProgress = spring({
    frame: frame - clickStartFrame,
    fps,
    config: { damping: 20, stiffness: 300 },
  });
  const releaseProgress = spring({
    frame: frame - clickReleaseFrame,
    fps,
    config: { damping: 15, stiffness: 200 },
  });

  // Button interactivity visual changes
  const buttonScale = 1 - pressProgress * 0.04 + releaseProgress * 0.04;
  const buttonBgOpacity = interpolate(pressProgress, [0, 1], [1, 0.8]) + interpolate(releaseProgress, [0, 1], [0, 0.2]);

  // 4. Outro Sequence
  const outroStartFrame = durationInFrames - 25;
  const outroSpring = spring({
    frame: frame - outroStartFrame,
    fps,
    config: { damping: 15, stiffness: 100 },
  });

  const finalCardScale = cardIntroProgress * interpolate(outroSpring, [0, 1], [1, 4]);
  const finalCardOpacity = interpolate(outroSpring, [0, 0.8], [1, 0], {
    extrapolateRight: "clamp",
  });

  // UI sizing calculations
  const cardWidth = Math.min(width * 0.4, 520);
  const cardPadding = 32;

  // Formatting helpers
  const initials = serverName
    .split(" ")
    .map((n) => n[0])
    .join("")
    .substring(0, 2)
    .toUpperCase();

  const formatNumber = (num: number) => new Intl.NumberFormat("en-US").format(num);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      {/* Background Ambience */}
      {particles.map((p, i) => {
        const yOffset = interpolate(
          frame,
          [0, durationInFrames],
          [p.y * height, p.y * height - p.speed]
        );
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: p.x * width,
              top: yOffset,
              width: p.size,
              height: p.size,
              borderRadius: "50%",
              backgroundColor: primaryColor,
              opacity: p.opacity * finalCardOpacity,
              filter: "blur(60px)",
              transition: "none",
            }}
          />
        );
      })}

      {/* Main Invite Card */}
      <div
        style={{
          width: cardWidth,
          backgroundColor: cardColor,
          borderRadius: 16,
          padding: cardPadding,
          display: "flex",
          flexDirection: "column",
          transform: `scale(${finalCardScale})`,
          opacity: finalCardOpacity,
          boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.5)",
          border: "1px solid rgba(255, 255, 255, 0.05)",
          transition: "none",
        }}
      >
        {/* Header: Inviter Context */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 12,
            marginBottom: 24,
            opacity: headerOpacity,
            transform: `translateY(${headerY}px)`,
            transition: "none",
          }}
        >
          {/* Inviter Avatar (Placeholder shape) */}
          <div
            style={{
              width: 24,
              height: 24,
              borderRadius: "50%",
              backgroundColor: "rgba(255, 255, 255, 0.1)",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
            }}
          >
            <div
              style={{
                width: 14,
                height: 14,
                borderRadius: "50%",
                backgroundColor: primaryColor,
              }}
            />
          </div>
          <p
            style={{
              margin: 0,
              fontSize: 14,
              color: "#a1a1aa", // zinc-400
              fontWeight: 500,
            }}
          >
            <span style={{ color: "#e4e4e7", fontWeight: 600 }}>{inviterName}</span> invited you to join
          </p>
        </div>

        {/* Server Context Row */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 20,
            marginBottom: 32,
          }}
        >
          {/* Server Icon */}
          <div
            style={{
              width: 72,
              height: 72,
              borderRadius: 20,
              backgroundColor: primaryColor,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              flexShrink: 0,
              transform: `scale(${serverIconSpring})`,
              boxShadow: `0 8px 24px -8px ${primaryColor}80`,
              transition: "none",
            }}
          >
            <span
              style={{
                color: "#ffffff",
                fontSize: 24,
                fontWeight: 800,
                letterSpacing: "-0.05em",
              }}
            >
              {initials}
            </span>
          </div>

          {/* Server Name & Stats */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: 8,
              opacity: serverInfoOpacity,
              transform: `translateX(${serverInfoX}px)`,
              transition: "none",
            }}
          >
            <h1
              style={{
                margin: 0,
                fontSize: 28,
                color: "#ffffff",
                fontWeight: 800,
                letterSpacing: "-0.02em",
                lineHeight: 1.1,
                whiteSpace: "nowrap",
                overflow: "hidden",
                textOverflow: "ellipsis",
                maxWidth: cardWidth - cardPadding * 2 - 92, // Card width - padding - icon width/gap
              }}
            >
              {serverName}
            </h1>

            {/* Stats Row */}
            <div style={{ display: "flex", gap: 16, alignItems: "center" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                <div
                  style={{
                    width: 10,
                    height: 10,
                    borderRadius: "50%",
                    backgroundColor: "#22c55e", // Green dot
                    boxShadow: "0 0 8px #22c55e80",
                  }}
                />
                <span style={{ color: "#a1a1aa", fontSize: 13, fontWeight: 500 }}>
                  {formatNumber(onlineCount)} Online
                </span>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                <div
                  style={{
                    width: 10,
                    height: 10,
                    borderRadius: "50%",
                    backgroundColor: "#52525b", // Gray dot
                  }}
                />
                <span style={{ color: "#a1a1aa", fontSize: 13, fontWeight: 500 }}>
                  {formatNumber(memberCount)} Members
                </span>
              </div>
            </div>
          </div>
        </div>

        {/* Join Button */}
        <div
          style={{
            width: "100%",
            height: 52,
            backgroundColor: primaryColor,
            borderRadius: 6,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transform: `scale(${buttonSpring * buttonScale})`,
            opacity: interpolate(buttonSpring, [0, 1], [0, buttonBgOpacity]),
            boxShadow: pressProgress > 0 && releaseProgress === 0
              ? `0 0 0 0 ${primaryColor}`
              : `0 4px 14px 0 ${primaryColor}60`,
            transition: "none",
          }}
        >
          <span
            style={{
              color: "#ffffff",
              fontSize: 16,
              fontWeight: 600,
              letterSpacing: "0.01em",
            }}
          >
            Join Server
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default DiscordJoinAnimation;